from collections import deque
def f(g):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==0 and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==0 and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and g[nr][nc]==0:
                seen[nr][nc]=True; q.append((nr,nc))
    return [[8 if g[r][c]==0 and not seen[r][c] else g[r][c] for c in range(w)] for r in range(h)]
