def comps(g,val=0):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==val and not seen[r][c]:
                q=[(r,c)]; seen[r][c]=True; cells=[]
                while q:
