# Frame bbox expansion: shrink-in, simpler: expand box outward while all border cells of new ring are 2. Careful with variable scoping.
def solve(gi):
    h,w=len(gi),len(gi[0]); seen=[[False]*w for _ in range(h)]; q=deque()
    seeds=[(r,c) for r in range(h) for c in (0,w-1) if gi[r][c]==0]+[(r,c) for c in range(w) for r in (0,h-1) if gi[r][c]==0]
    for r,c in seeds: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and gi[nr][nc]==0:
                seen[nr][nc]=True; q.append((nr,nc))
    out=[row[:] for row in gi]
    M={5:8,7:4,9:3}
    cc=[[False]*w for _ in range(h)]
    def frame_side(cells):
        top=min(a for a,b in cells); bot=max(a for a,b in cells)
        left=min(b for a,b in cells); right=max(b for a,b in cells)
        while True:
            tt=top-1; bb=bot+1; ll=left-1; rr_=right+1
            if tt<0 or bb>=h or ll<0 or rr_>=w: break
            if all(gi[tt][b]==2 and gi[bb][b]==2 for b in range(ll+1,rr_)) and \
               all(gi[a][ll]==2 and gi[a][rr_]==2 for a in range(tt+1,bb)):
                top,bot,left,right=tt,bb,ll,rr_
            else: break
        return max(bot-top,right-left)-2
    for r in range(h):
        for c in range(w):
            if gi[r][c]==0 and not seen[r][c] and not cc[r][c]:
                st=[(r,c)]; cc[r][c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dr,b+dc
                        if 0<=na<h and 0<=nb<w and not cc[na][nb] and gi[na][nb]==0:
                            cc[na][nb]=True; st.append((na,nb))
                s=frame_side(cells)
                col=M[s] if s in M else None
                if col is not None:
                    for a,b in cells: out[a][b]=col
    return out
